769	{
770	    struct mbox_env_tag *env = &mbox_env;
771	    RT_ASSERT(env->ipc_port == handle);
772	    rt_size_t len;
773	#ifdef BF0_HCPU
774	    hci_forward_env_t *hci_env = hci_forward_get_env();
