776	    if (hci_env->trans_en)
777	    {
778	        return hci_trans_mb_rx_ind(handle, size);
779	    }
780	#endif
781	
782	    if (NULL == env->rx.buf)
783	        return 0;
784	
785	    if (env->rx.data_size <= size)
786	    {
787	        len = ipc_queue_read(handle, env->rx.buf + env->rx.offset, env->rx.data_size);
788	        RT_ASSERT(len == env->rx.data_size);
789	        //LOG_D("mbox r l(%d, %d),d(%d)\r\n", len, env->rx.offset, *(env->rx.buf));
790	        env->rx.buf = NULL;
791	
792	        if (NULL != env->rx.callback)
793	        {
794	            env->rx.callback(env->rx.dummy, BT_EIF_STATUS_OK);
795	        }
796	    }
797	    else
798	    {
799	        len = ipc_queue_read(handle, env->rx.buf + env->rx.offset, size);
800	        RT_ASSERT(len == size);
801	        env->rx.data_size -= size;
802	        env->rx.offset += size;
803	    }
804	
805	    return 0;
806	
