190	__ROM_USED int32_t ipc_queue_open(ipc_queue_handle_t handle)
191	{
192	    int32_t result = -1;
193	    uint8_t *pool;
194	    uint32_t mask;
195	    ipc_queue_t *queue;
196	    int32_t offset;
197	
198	    if (!is_valid_handle(handle))
199	    {
200	        return result;
201	    }
202	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
203	    queue = &ipc_ctx.queues[offset];
204	
205	    mask = os_interrupt_disable();
206	
207	    if (queue->active)
208	    {
209	        goto __END;
210	    }
211	
212	    /* receiver no need to initialize the buffer as sender has already init the buffer */
213	    queue->rx_ring_buffer = (struct circular_buf *)queue->cfg.rx_buf_addr;
214	
215	    queue->tx_ring_buffer = (struct circular_buf *)queue->cfg.tx_buf_addr;
216	
217	    if (queue->tx_ring_buffer)
218	    {
219	        SF_ASSERT(queue->cfg.tx_buf_size > sizeof(struct circular_buf));
220	        /* sender initialize the buffer */
221	        pool = (uint8_t *)(queue->tx_ring_buffer + 1);
222	        circular_buf_wr_init(queue->tx_ring_buffer, pool, queue->cfg.tx_buf_size - sizeof(struct circular_buf));
223	
224	        /* update rd_buf_ptr */
225	        pool = (uint8_t *)((struct circular_buf *)queue->cfg.tx_buf_addr_alias + 1);
226	        circular_buf_rd_init(queue->tx_ring_buffer, pool, queue->cfg.tx_buf_size - sizeof(struct circular_buf));
227	    }
228	    result = ipc_hw_enable_interrupt(&queue->hw_q_handle, queue->cfg.qid, (uint32_t)handle);
229	
230	    if (0 == result)
231	    {
232	#if 0
233	#ifdef RT_USING_PM
234	        rt_pm_device_register((struct rt_device *)queue, &ipc_queue_pm_op);
235	#endif /* RT_USING_PM */
236	#endif
237	        queue->active = true;
238	    }
239	
240	__END:
241	    os_interrupt_enable(mask);
242	
243	    return result;
244	}
