517	void sifli_mbox_entry(void *param)
518	{
519	    uint32_t evt;
520	    uint32_t ptr;
521	
522	    os_event_create(evt_mailbox);
523	#ifdef OS_ADAPTOR_V2
524	    g_bf0_sible_mb = os_mailbox_create("sible_mb", 16, NULL);
525	#else
526	    os_mailbox_create(g_bf0_sible_mb, 16, NULL);
527	#endif
528	#ifdef SIBLES_TRANSPARENT_ENABLE
529	    is_trans_enable = 1; //TODO : Change to NVDS read
530	    if (is_trans_enable)
531	        sifli_transparent_output_init();
532	#endif
533	    OS_ASSERT(evt_mailbox && g_bf0_sible_mb);
534	    ble_power_on();
535	    // Due to ipc queue init first, to avoid miss isr from stack, just read once in the first loop.
536	    os_event_flags_set(evt_mailbox, SIFLI_TASK_RECV_EVT);
537	    LOG_I("Turn on BCPU\n");
538	    while (1)
539	    {
540	        os_event_flags_wait(evt_mailbox, SIFLI_TASK_EVT_ALL, OS_EVENT_FLAG_WAIT_ANY | OS_EVENT_FLAG_CLEAR, OS_WAIT_FORVER, &evt);
541	        if (evt & SIFLI_TASK_RECV_EVT)
542	        {
543	            rt_tick_t start_timer = rt_tick_get();
544	            while (1)
545	            {
546	                uint8_t ret;
547	                // First handle TX because TX data is simple.
548	#ifdef SIBLES_TRANSPARENT_ENABLE
549	                if (is_trans_enable)
550	                    ret = sifli_msg_transparent_process();
551	                else
552	#endif
553	                    ret = sifli_msg_process();
554	                if (ret == 0)
555	                    break;
556	
557	                // To avoid operation execute too much time, just switch to other evt and set evt again for this operation.
558	                if (sifli_msg_process_arbitration(start_timer, SIBLES_PROCESS_MAX_TICK) == 0)
559	                {
560	                    os_event_flags_set(evt_mailbox, SIFLI_TASK_RECV_EVT);
561	                    break;
562	                }
563	            }
564	        }
565	        if (evt & SIFLI_TASK_TRAN_EVT)
566	        {
567	            rt_tick_t start_timer = rt_tick_get();
568	            while (os_mailbox_get(g_bf0_sible_mb, &ptr, 0) == RT_EOK)
569	            {
570	                uint32_t ret = sifli_tx_msg_process((uint8_t *)ptr);
571	                if (ret == 0)
572	                    break;
573	
574	                // To avoid operation execute too much time, just switch to other evt and set evt again for this operation.
575	                if (sifli_msg_process_arbitration(start_timer, SIBLES_PROCESS_MAX_TICK) == 0)
576	                {
577	                    os_event_flags_set(evt_mailbox, SIFLI_TASK_TRAN_EVT);
578	                    break;
579	                }
580	            }
581	        }
582	#ifdef SIBLES_TRANSPARENT_ENABLE
583	        if (evt & SIFLI_TASK_TRAN_OUTPUT_EVT)
584	        {
585	            rt_tick_t start_timer = rt_tick_get();
586	            while (1)
587	            {
588	                rt_size_t len = sifli_transparent_output_handler();
589	                if (len == 0)
590	                    break;
591	
592	                // To avoid operation execute too much time, just switch to other evt and set evt again for this operation.
593	                if (sifli_msg_process_arbitration(start_timer, SIBLES_PROCESS_MAX_TICK) == 0)
594	                {
595	                    os_event_flags_set(evt_mailbox, SIFLI_TASK_TRAN_OUTPUT_EVT);
596	                    break;
597	                }
598	            }
599	        }
600	#endif
601	    }
602	}
